krpano.action:
try {
	if (!krpano || !krpano.get("webvr.isenabled")) return;
	var bg = krpano.get("hotspot[vr_nav_bg]");
	if (!bg || !bg.visible) return;

	var anchorH = 1.0 * krpano.get("vr_nav_anchor_h");
	var camV = 1.0 * krpano.get("view.vlookat");

	var atv = 38 + camV * 0.3;

	bg.ath = anchorH;
	bg.atv = atv;

	var hs0 = krpano.get("hotspot[vr_nav_icon_0]");
	if (hs0) { hs0.ath = anchorH + -27.0000; hs0.atv = atv; }
	var hs1 = krpano.get("hotspot[vr_nav_icon_1]");
	if (hs1) { hs1.ath = anchorH + -21.0000; hs1.atv = atv; }
	var hs2 = krpano.get("hotspot[vr_nav_icon_2]");
	if (hs2) { hs2.ath = anchorH + -15.0000; hs2.atv = atv; }
	var hs3 = krpano.get("hotspot[vr_nav_icon_3]");
	if (hs3) { hs3.ath = anchorH + -9.0000; hs3.atv = atv; }
	var hs4 = krpano.get("hotspot[vr_nav_icon_4]");
	if (hs4) { hs4.ath = anchorH + -3.0000; hs4.atv = atv; }
	var hs5 = krpano.get("hotspot[vr_nav_icon_5]");
	if (hs5) { hs5.ath = anchorH + 3.0000; hs5.atv = atv; }
	var hs6 = krpano.get("hotspot[vr_nav_icon_6]");
	if (hs6) { hs6.ath = anchorH + 9.0000; hs6.atv = atv; }
	var hs7 = krpano.get("hotspot[vr_nav_icon_7]");
	if (hs7) { hs7.ath = anchorH + 15.0000; hs7.atv = atv; }
	var hs8 = krpano.get("hotspot[vr_nav_icon_8]");
	if (hs8) { hs8.ath = anchorH + 21.0000; hs8.atv = atv; }
	var hs9 = krpano.get("hotspot[vr_nav_icon_9]");
	if (hs9) { hs9.ath = anchorH + 27.0000; hs9.atv = atv; }
} catch (e) {}

copy(vr_nav_anchor_h, view.hlookat);
set(hotspot[vr_nav_bg].visible, true);
set(hotspot[vr_nav_icon_0].visible, true);
set(hotspot[vr_nav_icon_1].visible, true);
set(hotspot[vr_nav_icon_2].visible, true);
set(hotspot[vr_nav_icon_3].visible, true);
set(hotspot[vr_nav_icon_4].visible, true);
set(hotspot[vr_nav_icon_5].visible, true);
set(hotspot[vr_nav_icon_6].visible, true);
set(hotspot[vr_nav_icon_7].visible, true);
set(hotspot[vr_nav_icon_8].visible, true);
set(hotspot[vr_nav_icon_9].visible, true);
vr_navbar_follow_update();
delayedcall(0, vr_navbar_follow_update());

set(hotspot[vr_nav_bg].visible, false);
set(hotspot[vr_nav_icon_0].visible, false);
set(hotspot[vr_nav_icon_1].visible, false);
set(hotspot[vr_nav_icon_2].visible, false);
set(hotspot[vr_nav_icon_3].visible, false);
set(hotspot[vr_nav_icon_4].visible, false);
set(hotspot[vr_nav_icon_5].visible, false);
set(hotspot[vr_nav_icon_6].visible, false);
set(hotspot[vr_nav_icon_7].visible, false);
set(hotspot[vr_nav_icon_8].visible, false);
set(hotspot[vr_nav_icon_9].visible, false);
